    let p = url.toString();
    if (p.startsWith("http://localhost/")) p = p.slice("http://localhost/".length);
    const full = path.join(outDir, p);
    return Promise.resolve({
        ok: true,
        status: 200,
        text: () => Promise.resolve(fs.readFileSync(full, "utf-8")),
    });
